import { useTranslation } from "react-i18next";

export function useNavBarTexts() {
    const { t } = useTranslation('navbar');
    return {
        about: t('about'),
        researchPlatform: t('research_platform'),
        test: t('test'),
        contact: t('contact'),
        dataSubTitle: {
            data: t('data_sub_title.data'),
            results: t('data_sub_title.results'),
            internalCalibration: t('data_sub_title.internal_calibration')
        },
        users: t('users'),
        profile: t('profile'),
        logout: t('logout'),
        login: t('login'),
        language: t('language'),
        rights: t('rights')
    };
}

