import {Container, Image} from "react-bootstrap";
import "./NavPagesInformation.css"
import {Link} from "react-router-dom";
import {Trans} from "react-i18next";
import {useResearchPlatformTexts} from "../translations/i18nHelpers";

export const ResearchPlatform = () => {
    const texts = useResearchPlatformTexts()

    return (
        <>
            <Container>

                <div className="text-start" id="researchPlatformPageContainer">
                    <h3 className="mt-3 fw-bold">{texts.title}</h3>

                    <p className="mt-4 mb-0 fw-bold">{texts.section1.title}</p>
                    <p className="mb-0">{texts.section1.paragraph}</p>

                    <ul>
                        <li>{texts.section1.bullet_pts[0]}</li>
                        <li>{texts.section1.bullet_pts[1]}</li>
                        <li>{texts.section1.bullet_pts[2]}</li>
                        <li>
                            {texts.section1.bullet_pts[3]}
                            <Link
                                className="btn-link"
                                to={"https://pubs.aip.org/asa/jasa/article/147/3/EL252/997279/Development-of-the-Canadian-Digit-Triplet-Test-in"}
                                target="_blank">{texts.section1.link}</Link>
                        </li>
                        <li>{texts.section1.bullet_pts[4]}</li>
                    </ul>

                    {/* Image of the user interface and accessories */}
                    <Image className="w-100"
                           src="https://raw.githubusercontent.com/MelinaRochon/CDTT_lists/main/Script/Images/Research-interface-EN.jpg"
                           alt="Research Interface"></Image>

                    <p className="mt-4 mb-0 fw-bold">{texts.section2.title}</p>
                    <ul>
                        <li>{texts.section2.bullet_pts[0]}</li>
                        <li>{texts.section2.bullet_pts[1]}</li>
                        <li>{texts.section2.bullet_pts[2]}</li>
                        <li>{texts.section2.bullet_pts[3]}</li>
                        <li>{texts.section2.bullet_pts[4]}</li>
                    </ul>

                    <p className="mt-4 mb-0">{texts.section3.title}</p>
                    <p className="mt-0 mb-0">{texts.section4.title}</p>

                    <p className="mt-4 mb-0 fw-bold">{texts.section5.title}</p>
                    <p className="m-0">
                        <Trans i18nKey={texts.section5.paragraph} components={{
                            formLink: (
                                <Link className="btn-link"
                                      to={"https://view.officeapps.live.com/op/view.aspx?src=https%3A%2F%2Fraw.githubusercontent.com%2FMelinaRochon%2FCDTT_lists%2Frefs%2Fheads%2Fmain%2FScript%2FNon-commercial_EULA_(CDTT)_Request_Form.docx&wdOrigin=BROWSELINK"}
                                      target="_blank" />
                            ),
                            contactLink: (
                                <Link className="btn-link" to={"/contact"} />
                            )
                        }}/>
                    </p>
                </div>
            </Container>
        </>
    )
}