import {Container} from "react-bootstrap";
import "./NavPagesInformation.css";
import {Link} from "react-router-dom";
import {useTranslation} from "react-i18next";
import {useContactTexts} from "../translations/i18nHelpers";

const Contact = () => {

    const texts = useContactTexts();

    return (
        <Container>
            <div className="text-start" id="contactPageContainer">
                <h3 className="mt-3 fw-bold">{texts.title}</h3>

                <p className="mt-4 mb-0 fw-bold">{texts.section1.title}</p>
                <p className="mb-0">
                    {texts.section1.names[0]} ({texts.university[0]}) - {texts.section1.email}
                    <Link className="btn-link"
                          to={`mailto:${texts.section1.emails[0]}`}>{texts.section1.emails[0]}</Link>
                    <br/>
                    {texts.section1.names[1]} ({texts.university[0]}) - {texts.section1.email}
                    <Link className="btn-link"
                          to={`mailto:${texts.section1.emails[1]}`}>{texts.section1.emails[1]}</Link>
                    <br/>
                    {texts.section1.names[2]} ({texts.university[1]}) - {texts.section1.email}
                    <Link className="btn-link"
                          to={`mailto:${texts.section1.emails[2]}`}>{texts.section1.emails[2]}</Link>
                </p>

                <p className="mt-4 mb-0 fw-bold">{texts.section2.title}</p>
                <p className="mb-0">
                    {texts.section2.names[0]}
                    <br/>
                    {texts.section2.names[1]}
                </p>

                <p className="mt-5 fst-italic">{texts.rights}</p>
            </div>
        </Container>
    )
}

export default Contact;