import {Button, Card} from "react-bootstrap";
import InputMask from "react-input-mask";
import React from "react";

function Keypad({
                    inputUserText,
                    keyboardListener,
                    keypadDigitListener,
                    keypadDeleteListener,
                    keypadSubmitListener,
                    disableKeys,
                    enableKeyboard,
                    bDisableDelete,
                    bDisableSubmit,
                    bNotReadyForAnswer,
                    audioIsOn
                }) {
    return (
        <div className="d-flex justify-content-center">
            <Card className="mt-4 mb-2" style={{maxWidth: '300px'}}>
                <Card.Body className="p-0">
                    <tr>
                        <th colSpan="3">
                            <InputMask
                                className="inputUserKeyboard"
                                name="inputUserText"
                                id="inputUserText"
                                mask="999"
                                maskChar={""}
                                value={inputUserText}
                                onChange={keyboardListener}
                                disabled={!bDisableSubmit || disableKeys || enableKeyboard}
                            ></InputMask>
                        </th>
                    </tr>
                    {/* <!-- Row 2: 1-2-3 buttons --> */}
                    <tr>
                        <td>
                            <center>
                                <Button
                                    id={"btn1"}
                                    className="testKeyboardBtn my-1"
                                    variant={'outline-secondary'}
                                    onClick={() => keypadDigitListener(1)}
                                    disabled={disableKeys || enableKeyboard}
                                >1</Button>
                            </center>
                        </td>
                        <td>
                            <center>
                                <Button
                                    id={"btn2"}
                                    className="testKeyboardBtn my-1"
                                    variant={'outline-secondary'}
                                    onClick={() => keypadDigitListener(2)}
                                    disabled={disableKeys || enableKeyboard}
                                >2</Button>
                            </center>
                        </td>
                        <td>
                            <center>
                                <Button id={"btn3"} className="testKeyboardBtn my-1" variant={'outline-secondary'}
                                        onClick={() => keypadDigitListener(3)}
                                        disabled={disableKeys || enableKeyboard}>3</Button>
                            </center>
                        </td>
                    </tr>
                    {/* <!-- Row 3: 4-5-6 buttons --> */}
                    <tr>
                        <td>
                            <center>
                                <Button id={"btn4"} className="testKeyboardBtn my-1" variant={'outline-secondary'}
                                        onClick={() => keypadDigitListener(4)}
                                        disabled={disableKeys || enableKeyboard}>4</Button>
                            </center>
                        </td>
                        <td>
                            <center>
                                <Button id={"btn5"} className="testKeyboardBtn my-1" variant={'outline-secondary'}
                                        onClick={() => keypadDigitListener(5)}
                                        disabled={disableKeys || enableKeyboard}>5</Button>
                            </center>
                        </td>
                        <td>
                            <center>
                                <Button id={"btn6"} className="testKeyboardBtn my-1" variant={'outline-secondary'}
                                        onClick={() => keypadDigitListener(6)}
                                        disabled={disableKeys || enableKeyboard}>6</Button>
                            </center>
                        </td>
                    </tr>
                    {/* <!-- Row 4: 7-8-9 buttons --> */}
                    <tr>
                        <td>
                            <center>
                                <Button id={"btn7"} className="testKeyboardBtn my-1" variant={'outline-secondary'}
                                        onClick={() => keypadDigitListener(7)}
                                        disabled={disableKeys || enableKeyboard}>7</Button>
                            </center>
                        </td>
                        <td>
                            <center>
                                <Button id={"btn8"} className="testKeyboardBtn my-1" variant={'outline-secondary'}
                                        onClick={() => keypadDigitListener(8)}
                                        disabled={disableKeys || enableKeyboard}>8</Button>
                            </center>
                        </td>
                        <td>
                            <center>
                                <Button id={"btn9"} className="testKeyboardBtn my-1" variant={'outline-secondary'}
                                        onClick={() => keypadDigitListener(9)}
                                        disabled={disableKeys || enableKeyboard}>9</Button>
                            </center>
                        </td>
                    </tr>
                    {/* <!-- Row 5: Delete-0-Submit buttons --> */}
                    <tr>
                        {/* <!-- Delete button --> */}
                        <td>
                            <center>
                                <Button id={"btnDelete"} className="testKeyboardBtn btnDelete mt-1 mb-2"
                                        variant={'outline-secondary'}
                                        onClick={keypadDeleteListener}
                                        disabled={bDisableDelete || enableKeyboard}>
                                    <a><img
                                        src="https://raw.githubusercontent.com/MelinaRochon/CDTT_lists/main/Script/Images/icon-delete.png"
                                        id="iconDelete" alt="Delete"/></a>
                                </Button>
                            </center>
                        </td>
                        <td>
                            <center>
                                <Button id={"btn0"} className="testKeyboardBtn mt-1 mb-2"
                                        variant={'outline-secondary'}
                                        onClick={() => keypadDigitListener(0)}
                                        disabled={disableKeys || enableKeyboard}>0</Button>
                            </center>
                        </td>
                        {/* <!-- Submit button --> */}
                        <td>
                            <center>
                                <Button id={"btnSubmit"} className="testKeyboardBtn btnSubmit mt-1 mb-2"
                                        variant={'outline-secondary'}
                                        onClick={keypadSubmitListener}
                                        disabled={(bDisableSubmit || bNotReadyForAnswer) || audioIsOn}>
                                    <img
                                        src="https://raw.githubusercontent.com/MelinaRochon/CDTT_lists/main/Script/Images/icon-enter.png"
                                        id="iconEnter" alt="Submit"/>
                                </Button>
                            </center>
                        </td>
                    </tr>
                </Card.Body>
            </Card>
        </div>
    );
}

export default Keypad;