import {Container} from "react-bootstrap";
import "./NavPagesInformation.css";
import {Link} from "react-router-dom";
import {Trans} from "react-i18next";
import {useAboutTexts} from "../translations/i18nHelpers";

export const HomePage = () => {
    const about = useAboutTexts();

    return (
        <>
            <Container>
                <div className="text-start" id="aboutPageContainer">
                    <h3 className="mt-3 fw-bold">{about.title}</h3>
                    <p className="mt-4 mb-0">
                        <Trans i18nKey={about.paragraph1} components={{
                            icraLink: (
                                <Link className="btn-link" to={"https://icra-audiology.org/"} target="_blank"/>
                            ),
                            multilangualSpeechLink: (
                                <Link className="btn-link" target="_blank"
                                      to={"https://www.tandfonline.com/doi/full/10.3109/14992027.2015.1030513"}/>
                            )
                        }}/>
                    </p>
                    <div className="d-flex flex-column align-items-start mt-2 mb-2">
                        <Link className="btn-link" to={"https://canadianaudiologist.ca/u-of-o-feature-4/"}
                              target="_blank">{about.link_title[0]}</Link>
                        <Link className="btn-link mb-1"
                              to={"https://pubs.aip.org/asa/jasa/article/147/3/EL252/997279/Development-of-the-Canadian-Digit-Triplet-Test-in"}
                              target="_blank">{about.link_title[1]}</Link>
                    </div>

                    <p>{about.paragraph2.beforeLink1}
                        <Link className="btn-link"
                              to={"https://ccna-ccnv.ca/en/"}
                              target="_blank">{about.paragraph2.links[0]}</Link>
                        {about.paragraph2.betweenLinks}
                        <Link className="btn-link" to={"https://www.clsa-elcv.ca/"}
                              target="_blank">{about.paragraph2.links[1]}</Link>
                        {about.paragraph2.afterLink}
                    </p>

                    <ul>
                        <li>
                            <Trans i18nKey={about.paragraph2.bullet_pts[0]} components={{
                                goToLink: (
                                    <Link className="btn-link" to={"/researchPlatform"} />
                                )
                            }}/>
                        </li>
                        <li>
                            <Trans i18nKey={about.paragraph2.bullet_pts[1]} components={{
                                goToLink: (
                                    <Link className="btn-link" to={"/test"} />
                                )
                            }}/>
                        </li>
                    </ul>
                </div>
            </Container>
        </>
    );
}